-- RLS tests for public.opponents
begin;
create extension if not exists pgtap with schema extensions;
select * from no_plan();
create function pg_temp.n(q text) returns int language plpgsql as $f$ declare c int; begin execute q; get diagnostics c = row_count; return c; end $f$;

update public.profiles set display_name = 'Pat Ava' where id = 'a2222222-2222-2222-2222-222222222222';
-- Team A (club-linked, soccer): admin, coach, parents Ava/Ben, player Teen. Team B (basketball): coach B, parent Other.
-- Active on A: Ava, Ben, Teen. Inactive on A: Dan. Active on B: Cleo, Ivy (Ava's second team).

reset role;
reset role; set local role anon; select set_config('request.jwt.claims', '{"role":"anon"}', true);
select throws_ok($$ select * from public.opponents $$, '42501', null, 'anonymous users cannot read opponents');
reset role; select set_config('request.jwt.claims', '{"sub":"a8888888-8888-8888-8888-888888888888","role":"authenticated"}', true); set local role authenticated;
select is((select name from public.opponents), 'Hawks', 'staff read only their team''s opponents');
select lives_ok($$ insert into public.opponents (team_id, name) values ('a1000000-0000-0000-0000-00000000000a', 'Eagles') $$, 'staff add an opponent');
select throws_ok($$ insert into public.opponents (team_id, name) values ('a1000000-0000-0000-0000-00000000000a', 'Eagles') $$, '23505', null, 'opponent names are unique per team');
select throws_ok($$ insert into public.opponents (team_id, name) values ('a2000000-0000-0000-0000-00000000000b', 'Sneaky') $$, '42501', null, 'staff cannot add an opponent to another team');
select is(pg_temp.n($q$update public.opponents set name = 'Hawks FC' where id = '10a00000-0000-0000-0000-00000000000a'$q$), 1, 'staff rename an opponent');
select is(pg_temp.n($q$update public.opponents set name = 'x' where id = '10a00000-0000-0000-0000-00000000000b'$q$), 0, 'staff cannot edit another team''s opponent');
select is(pg_temp.n($q$delete from public.opponents where name = 'Eagles'$q$), 1, 'staff delete their opponent');
select is(pg_temp.n($q$delete from public.opponents where id = '10a00000-0000-0000-0000-00000000000b'$q$), 0, 'staff cannot delete another team''s opponent');
reset role; select set_config('request.jwt.claims', '{"sub":"a2222222-2222-2222-2222-222222222222","role":"authenticated"}', true); set local role authenticated;
select is((select count(*)::int from public.opponents), 2, 'a parent with kids on two teams reads both teams'' opponents');
select throws_ok($$ insert into public.opponents (team_id, name) values ('a1000000-0000-0000-0000-00000000000a', 'Parent FC') $$, '42501', null, 'parents cannot add opponents');
reset role; select set_config('request.jwt.claims', '{"sub":"a4444444-4444-4444-4444-444444444444","role":"authenticated"}', true); set local role authenticated;
select is((select count(*)::int from public.opponents where team_id = 'a1000000-0000-0000-0000-00000000000a'), 0, 'a parent on team B cannot read team A opponents');
reset role; select set_config('request.jwt.claims', '{"sub":"a5555555-5555-5555-5555-555555555555","role":"authenticated"}', true); set local role authenticated;
select is((select count(*)::int from public.opponents), 1, 'a linked club admin reads the team''s opponents');
select throws_ok($$ insert into public.opponents (team_id, name) values ('a1000000-0000-0000-0000-00000000000a', 'Club FC') $$, '42501', null, 'a club admin cannot add opponents');
reset role; select set_config('request.jwt.claims', '{"sub":"a9999999-9999-9999-9999-999999999999","role":"authenticated"}', true); set local role authenticated;
select is((select count(*)::int from public.opponents), 0, 'a stranger reads nothing');
select * from finish();
rollback;
